import { spawn, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createServer } from 'node:net';
import { existsSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir, homedir } from 'node:os';
import { join } from 'node:path';
import { gunzipSync } from 'node:zlib';

const deadline = Date.now() + 285_000;
const children = new Set();
let cdp = null;
let outcome = 2;

function remaining() {
  return Math.max(1_000, deadline - Date.now());
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function run(command, args, timeout) {
  const result = spawnSync(command, args, {
    cwd: process.cwd(),
    env: { ...process.env, NEXT_TELEMETRY_DISABLED: '1' },
    encoding: 'utf8',
    timeout: Math.min(timeout, remaining()),
    maxBuffer: 20 * 1024 * 1024,
  });
  if (result.error || result.status !== 0) {
    const detail = [result.stdout, result.stderr, result.error?.message].filter(Boolean).join('\n');
    throw new Error(`${command} ${args.join(' ')} failed (${result.status ?? 'no status'})\n${detail.slice(-12_000)}`);
  }
}

function findChrome() {
  const explicit = [
    process.env.CHROME_PATH,
    process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH,
    '/usr/bin/google-chrome',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
  ].filter(Boolean);
  for (const file of explicit) if (existsSync(file)) return file;
  const roots = [process.env.PLAYWRIGHT_BROWSERS_PATH, join(homedir(), '.cache', 'ms-playwright')].filter(Boolean);
  for (const root of roots) {
    if (!existsSync(root)) continue;
    const versions = readdirSync(root).filter(name => name.startsWith('chromium-')).sort().reverse();
    for (const version of versions) {
      for (const relative of ['chrome-linux64/chrome', 'chrome-linux/chrome', 'chrome-linux/headless_shell']) {
        const file = join(root, version, relative);
        if (existsSync(file)) return file;
      }
    }
  }
  throw new Error('No Chromium executable is available for the browser-level check');
}

const DEVTOOLS_BACKEND_GZIP_BASE64 = '';

function fetchDevToolsBackend() {
  const source = gunzipSync(Buffer.from(DEVTOOLS_BACKEND_GZIP_BASE64, 'base64')).toString('utf8');
  const digest = createHash('sha256').update(source).digest('hex');
  if (digest !== 'f4a87d5167303938432a16a70b52fbb65f8eebe4320677459bf619c9df23bfd0') {
    throw new Error(`Embedded React DevTools 6.1.2 backend integrity mismatch: ${digest}`);
  }
  return source;
}

async function freePort() {
  return await new Promise((resolve, reject) => {
    const server = createServer();
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      server.close(error => error ? reject(error) : resolve(address.port));
    });
  });
}

async function waitForHttp(url, child) {
  let lastError = '';
  while (Date.now() < deadline && child.exitCode == null) {
    try {
      const response = await fetch(url, { signal: AbortSignal.timeout(2_000) });
      if (response.ok) return response;
      lastError = `HTTP ${response.status}`;
    } catch (error) {
      lastError = error.message;
    }
    await sleep(250);
  }
  throw new Error(`Service did not become ready at ${url}: ${lastError}`);
}

async function stopChild(child) {
  if (!child || child.exitCode != null) return;
  child.kill('SIGTERM');
  await Promise.race([new Promise(resolve => child.once('exit', resolve)), sleep(5_000)]);
  if (child.exitCode == null) child.kill('SIGKILL');
}

class CDP {
  constructor(url) {
    this.socket = new WebSocket(url);
    this.nextId = 1;
    this.pending = new Map();
    this.events = [];
  }
  async open() {
    await new Promise((resolve, reject) => {
      this.socket.addEventListener('open', resolve, { once: true });
      this.socket.addEventListener('error', reject, { once: true });
    });
    this.socket.addEventListener('message', event => {
      const message = JSON.parse(event.data);
      if (message.id) {
        const pending = this.pending.get(message.id);
        if (!pending) return;
        this.pending.delete(message.id);
        if (message.error) pending.reject(new Error(`${pending.method}: ${message.error.message}`));
        else pending.resolve(message.result);
      } else {
        this.events.push(message);
      }
    });
  }
  send(method, params = {}, sessionId) {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject, method });
      this.socket.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
    });
  }
  close() {
    this.socket.close();
  }
}

async function evaluate(sessionId, expression) {
  const response = await cdp.send('Runtime.evaluate', {
    expression,
    awaitPromise: true,
    returnByValue: true,
  }, sessionId);
  if (response.exceptionDetails) {
    throw new Error(`Browser evaluation failed: ${response.exceptionDetails.exception?.description || response.exceptionDetails.text}`);
  }
  return response.result.value;
}

async function waitForExpression(sessionId, expression, timeout = 30_000) {
  const end = Date.now() + Math.min(timeout, remaining());
  let lastError;
  while (Date.now() < end) {
    try {
      if (await evaluate(sessionId, expression)) return;
    } catch (error) {
      lastError = error;
    }
    await sleep(200);
  }
  throw new Error(`Browser condition timed out: ${expression}; ${lastError?.message || ''}`);
}

try {
  const backendSource = await fetchDevToolsBackend();
  run(process.execPath, ['node_modules/next/dist/bin/next', 'build'], 180_000);

  const appPort = await freePort();
  const server = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '-H', '127.0.0.1', '-p', String(appPort)], {
    cwd: process.cwd(),
    env: { ...process.env, NEXT_TELEMETRY_DISABLED: '1' },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  children.add(server);
  let serverOutput = '';
  server.stdout.on('data', chunk => { serverOutput = (serverOutput + chunk).slice(-12_000); });
  server.stderr.on('data', chunk => { serverOutput = (serverOutput + chunk).slice(-12_000); });
  const appUrl = `http://127.0.0.1:${appPort}/`;
  await waitForHttp(appUrl, server);

  const debugPort = await freePort();
  const profileDir = join(tmpdir(), `next-80464-chrome-${process.pid}-${Date.now()}`);
  const chrome = spawn(findChrome(), [
    '--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu',
    `--remote-debugging-port=${debugPort}`, `--user-data-dir=${profileDir}`, 'about:blank',
  ], { stdio: ['ignore', 'pipe', 'pipe'] });
  children.add(chrome);
  chrome.once('exit', () => rmSync(profileDir, { recursive: true, force: true }));

  const versionResponse = await waitForHttp(`http://127.0.0.1:${debugPort}/json/version`, chrome);
  const { webSocketDebuggerUrl } = await versionResponse.json();
  cdp = new CDP(webSocketDebuggerUrl);
  await cdp.open();

  const { targetId } = await cdp.send('Target.createTarget', { url: 'about:blank' });
  const { sessionId } = await cdp.send('Target.attachToTarget', { targetId, flatten: true });
  await cdp.send('Runtime.enable', {}, sessionId);
  await cdp.send('Page.enable', {}, sessionId);

  const setup = `${backendSource}\n;(() => {
    const inbound = new Set();
    const emitted = [];
    ReactDevToolsBackend.initialize({
      appendComponentStack: true,
      breakOnConsoleErrors: false,
      showInlineWarningsAndErrors: true,
      hideConsoleLogsInStrictMode: false
    });
    const hook = window.__REACT_DEVTOOLS_GLOBAL_HOOK__;
    window.__NEXT_80464__ = { traces: [], emitted, inbound };
    hook.sub('traceUpdates', nodes => {
      window.__NEXT_80464__.traces.push(Array.from(nodes, node => ({
        tag: node?.tagName || null,
        text: node?.textContent?.replace(/\\s+/g, ' ').trim() || '',
        html: node?.outerHTML?.slice(0, 500) || ''
      })));
    });
    ReactDevToolsBackend.connectWithCustomMessagingProtocol({
      onSubscribe(listener) { inbound.add(listener); },
      onUnsubscribe(listener) { inbound.delete(listener); },
      onMessage(event, payload) { emitted.push({ event, payload }); }
    });
    window.__NEXT_80464__.send = (event, payload) => {
      for (const listener of inbound) listener({ event, payload });
    };
  })();`;
  await cdp.send('Page.addScriptToEvaluateOnNewDocument', { source: setup }, sessionId);
  await cdp.send('Page.navigate', { url: appUrl }, sessionId);
  await waitForExpression(sessionId, `(() => {
    const state = window.__NEXT_80464__;
    const hook = window.__REACT_DEVTOOLS_GLOBAL_HOOK__;
    return !!(state && state.inbound.size > 0 && hook?.renderers?.size > 0 && document.body?.innerText.includes('Increment'));
  })()`);

  await evaluate(sessionId, `(() => {
    window.__NEXT_80464__.traces.length = 0;
    window.__NEXT_80464__.send('setTraceUpdatesEnabled', true);
    const button = Array.from(document.querySelectorAll('button')).find(node => node.textContent.trim() === 'Increment');
    if (!button) throw new Error('Increment button not found');
    button.click();
    return true;
  })()`);
  await waitForExpression(sessionId, `document.body?.innerText.includes('Count 1')`, 10_000);
  await sleep(1_000);

  const observation = await evaluate(sessionId, `(() => ({
    visibleText: document.body.innerText.replace(/\\s+/g, ' ').trim(),
    traces: window.__NEXT_80464__.traces,
    rendererCount: window.__REACT_DEVTOOLS_GLOBAL_HOOK__.renderers.size
  }))()`);
  const traced = observation.traces.flat();
  const client1Highlighted = traced.some(node => node.text === 'first client component');
  const counterHighlighted = traced.some(node => node.text.includes('Count 1') || node.text === 'Increment');
  console.log(JSON.stringify({
    symptom: 'React DevTools 6.1.2 highlight-updates backend marks both client component regions after only Client2 state changes',
    client1Highlighted,
    counterHighlighted,
    ...observation,
  }, null, 2));
  outcome = client1Highlighted && counterHighlighted ? 0 : 1;
} catch (error) {
  console.error(error?.stack || error);
  outcome = 2;
} finally {
  process.exitCode = outcome;
  if (cdp) cdp.close();
  await Promise.all(Array.from(children, stopChild));
}
